-- Base64 encoded payload loader for script-29.lua
local b64 = [=[]=]
local function decode(data)
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, #chars do map[chars:sub(i, i)] = i - 1 end
    local parts, buf, n = {}, {}, 0
    local function emit(b)
        n = n + 1; buf[n] = string.char(b)
        if n >= 4096 then parts[#parts+1] = table.concat(buf); for j=1,n do buf[j]=nil end; n=0 end
    end
    local i = 1
    while i <= #data do
        local e3, e4 = data:sub(i+2,i+2), data:sub(i+3,i+3)
        local c1 = map[data:sub(i,i)] or 0
        local c2 = map[data:sub(i+1,i+1)] or 0
        local c3 = (e3 == "=" or e3 == "") and 0 or (map[e3] or 0)
        local c4 = (e4 == "=" or e4 == "") and 0 or (map[e4] or 0)
        local v = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        emit(math.floor(v / 65536) % 256)
        if e3 ~= "=" and e3 ~= "" then emit(math.floor(v / 256) % 256) end
        if e4 ~= "=" and e4 ~= "" then emit(v % 256) end
        i = i + 4
    end
    if n > 0 then parts[#parts+1] = table.concat(buf) end
    return table.concat(parts)
end
local src = decode(b64)
local fn, err = loadstring(src) or load(src)
if not fn then error("decode/load failed: " .. tostring(err)) end
return fn()
